import * as G from './game.js';
const KEY='thanh-van-tong-v1';
const isPreview=new URLSearchParams(location.search).get('preview')==='1';
const $=q=>document.querySelector(q);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const fmt=n=>Math.floor(n).toLocaleString('vi-VN');
const compact=n=>n>=1e6?(n/1e6).toFixed(1)+'tr':n>=1e4?(n/1e3).toFixed(1)+'k':fmt(n);
const resourceNames={stone:'Linh thạch',wood:'Linh mộc',herb:'Linh thảo',ore:'Linh khoáng',qi:'Linh khí'};
let savedRaw;try{if(!isPreview)savedRaw=localStorage.getItem(KEY)}catch{}
const restored=G.restore(savedRaw);let state=restored.state,view='home',currentModal='',battle=null,battleTimer=null,battleSpeed=1,saveFailed=false,importCandidate=null;
const modal=$('#modal');
function toast(text,type=''){const node=document.createElement('div');node.className='toast '+type;node.textContent=text;$('#toasts').append(node);setTimeout(()=>node.remove(),3400);}
function save(){if(isPreview){$('#save-status').textContent='Bản xem bố cục · Không lưu tiến trình';return;}try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='Đã lưu · Tiến trình trên thiết bị';$('#save-status').classList.remove('save-warning');saveFailed=false;}catch{if(!saveFailed)toast('Trình duyệt không cho lưu. Bạn có thể xuất tiến trình trong Cài đặt.','error');saveFailed=true;$('#save-status').textContent='Chưa lưu được · Hãy xuất tiến trình';$('#save-status').classList.add('save-warning');}}
function costMarkup(cost){return `<div class="cost">${Object.entries(cost).map(([k,v])=>`<span class="${state[k]<v?'missing':''}" title="${resourceNames[k]}">${icon(k)} ${fmt(v)}</span>`).join('')}</div>`;}
function portrait(d,master=false){const cell=master?6:d.appearance%6;return `<span class="character-art" style="--cell-x:${(cell%4)/3*100}%;--cell-y:${Math.floor(cell/4)*100}%" aria-hidden="true"></span>`;}
function beast(d){const hue={Mộc:0,Thổ:35,Hỏa:155,Thủy:0,Kim:300}[d.element]||0;return `<span class="character-art enemy-art" style="--cell-x:100%;--cell-y:100%;--spirit-hue:${hue}deg" aria-hidden="true"></span>`;}
function renderHeader(){$('#resources').innerHTML=Object.keys(resourceNames).map(k=>`<div class="resource" title="${resourceNames[k]}">${icon(k)}<div><b data-resource="${k}">${compact(state[k])}</b><small>${resourceNames[k]}</small></div></div>`).join('');$('#sound-toggle').classList.toggle('on',state.sound);$('#sound-toggle').setAttribute('aria-pressed',String(state.sound));}
function heading(title,sub,tools='',home=false){return `<div class="page-heading"><div><div class="eyebrow">${home?'KHAI SƠN LẬP PHÁI':'THANH VÂN TÔNG'}</div><h1>${title}</h1><p>${sub}</p></div>${tools||'<div class="day-badge"><span class="sun">☼</span><span>Vân hải an nhiên<br>Tiên đạo hữu duyên</span></div>'}</div>`;}
const markerPositions={hall:[52,25],wood:[17,36],herb:[27,60],ore:[83,35],qi:[80,67],alchemy:[54,54]};
function masterMarkup(){const cost=G.realmCost(state);const full=state.realm===G.REALMS.length-1;return `<div class="panel master-panel"><div class="panel-label"><h3>Tông sư</h3><small>TÂM TĨNH · ĐẠO SINH</small></div><div class="master-top"><div class="master-avatar">${portrait({element:'Thủy',appearance:1},true)}</div><div class="master-info"><h3>Vân Du</h3><span class="realm-tag">${G.REALMS[state.realm]}</span><small>${full?'Tiên đồ viên mãn':'Hướng tới '+G.REALMS[state.realm+1]}</small></div></div><div class="cultivation"><div class="cultivation-label"><span>Tu vi tích lũy</span><span data-qi-progress>${fmt(state.qi)} / ${fmt(cost.qi)}</span></div><div class="progress"><span data-qi-bar style="width:${Math.min(100,state.qi/cost.qi*100)}%"></span></div></div><div class="master-buttons"><button class="btn secondary" data-action="meditate">Tĩnh tâm</button><button class="btn" data-action="realm">${full?'Viên mãn':'Đột phá'} ${icon('arrow')}</button></div><div class="power-row"><span>Chiến lực đội hình</span><strong data-power>${fmt(G.power(state))}</strong></div></div>`;}
function questMarkup(){const qs=G.QUESTS.filter(q=>!state.claimed.includes(q.id)).slice(0,3);return `<div class="panel"><div class="panel-label"><h3>Tiên môn ký sự</h3><small>${state.claimed.length}/${G.QUESTS.length}</small></div><div class="quest-list">${qs.map(q=>{const ready=q.value(state)>=q.target;return `<div class="quest"><div class="quest-icon">${icon(ready?'check':'scroll')}</div><div class="quest-content"><b>${q.name}</b><small>${q.desc}</small></div><button class="quest-claim ${ready?'complete':''}" data-action="claim" data-id="${q.id}" ${ready?'':'disabled'}>${ready?'Nhận':Math.min(q.value(state),q.target)+'/'+q.target}</button></div>`}).join('')||'<div class="empty-state">Ký sự đã hoàn thành.<br>Tiên đồ còn rộng, tiếp tục khám phá!</div>'}</div></div>`;}
function homeMarkup(){const r=G.rates(state);return heading('Thanh Vân Sơn','Khai sơn lập phái · Một tông môn, vạn dặm tiên đồ.',`<div class="day-badge"><i class="live-dot"></i><span>Tiên môn cấp ${state.buildings.hall}<br>${state.disciples.length} đệ tử đồng hành</span></div>`,true)+`<div class="dashboard"><div class="world-column"><div class="map-card"><div class="map-toolbar"><div class="map-location">${icon('mountain')}<div><b>Vân hải tiên môn</b><small>LINH MẠCH THANH VÂN</small></div></div><span class="map-live"><i class="live-dot"></i> ${state.disciples.filter(d=>d.job!=='idle').length} đệ tử đang làm việc</span></div><div class="world"><picture><source media="(max-width:700px)" srcset="assets/sect-world-mobile.webp?v=2.2.0"><img class="world-art" src="assets/sect-world.webp?v=2.2.0" width="1536" height="1024" fetchpriority="high" alt="Tiên môn giữa biển mây với điện chính, linh điền, hồ sen, mỏ khoáng và các công trình tu tiên"></picture><div class="clouds"></div><div class="world-particles" aria-hidden="true">${[0,1,2,3,4,5].map(i=>`<i style="--n:${i}"></i>`).join('')}</div>${G.BUILDINGS.map(b=>`<button class="building-marker" style="left:${markerPositions[b.id][0]}%;top:${markerPositions[b.id][1]}%" data-action="building" data-id="${b.id}" aria-label="${b.name}, cấp ${state.buildings[b.id]}"><b>${b.name}</b><small><span>${b.resource?'+'+(r[b.resource]*60).toFixed(0)+'/phút':'Luyện đan'}</span><span class="lv">C${state.buildings[b.id]}</span></small><div class="mini-progress"><span data-live-progress="${b.id}" style="width:${40+state.buildings[b.id]*5}%"></span></div></button>`).join('')}</div><div class="map-bottom"><div><strong><i class="live-dot"></i>Linh mạch đang sinh sôi</strong><p>Đệ tử tự sản xuất · Tích lũy khi nghỉ tối đa 8 giờ</p></div><div class="world-actions"><button class="btn secondary" data-action="recruit">${icon('users')} Chiêu mộ</button><button class="btn gold" data-nav="adventure">${icon('sword')} Vào bí cảnh</button></div></div></div><div class="section-row"><h2>Đệ tử đồng hành</h2><button class="btn ghost" data-nav="disciples">${state.disciples.length} đệ tử ${icon('arrow')}</button></div><div class="disciple-strip">${state.disciples.slice(0,3).map(d=>`<button class="small-disciple" data-action="disciple" data-id="${d.id}"><div class="portrait">${portrait(d)}</div><div><b>${escape(d.name)}</b><small>${d.element} linh căn · Cấp ${d.level}</small><small class="job-status"><i class="live-dot"></i>${G.JOBS[d.job]}</small></div></button>`).join('')}</div><div class="activity-panel">${icon('scroll')}<span><b>Tiên môn ký</b> &nbsp; <span id="latest-log">${escape(state.log[0]?.text||'Tông môn bình yên.')}</span></span><span class="activity-time">Vừa cập nhật</span></div></div><div class="right-stack">${masterMarkup()}${questMarkup()}<div class="journey-card"><span class="eyebrow">TIÊN DUYÊN KỲ NGỘ</span><h3>Tiên đồ rộng mở</h3><p>${G.CHAPTERS[state.chapter].name} đang chờ đệ tử thám hiểm.</p><button class="btn gold block" data-nav="adventure">Khám phá bí cảnh ${icon('arrow')}</button></div></div></div>`;}
function jobOptions(d){return Object.entries(G.JOBS).map(([id,name])=>`<option value="${id}" ${id===d.job?'selected':''}>${name}${(d.element==='Mộc'&&id==='herb')||(d.element==='Kim'&&id==='ore')||(d.element==='Thủy'&&id==='qi')||(d.element==='Thổ'&&id==='wood')?' · hợp linh căn':''}</option>`).join('');}
function disciplesMarkup(){return heading('Đệ tử tông môn','Mỗi linh căn, một sở trường. Giao việc và bồi dưỡng đệ tử để tiên môn lớn mạnh.',`<div class="page-tools"><span class="soft-badge">${state.disciples.length}/${G.capacity(state)} đệ tử</span><button class="btn" data-action="recruit">${icon('users')} Chiêu mộ${state.scrolls?' · '+state.scrolls+' miễn phí':''}</button></div>`)+`<div class="guide-callout">${icon('users')}<span>Chọn tối đa 5 đệ tử xuất chiến. Đệ tử vẫn sản xuất khi thuộc đội hình.</span><button class="btn secondary" data-action="building" data-id="hall">Mở rộng tông môn</button></div><div class="disciples-grid">${state.disciples.map(d=>`<article class="disciple-card"><span class="badge rarity-${d.rarity}">${d.rarity}</span><div class="portrait">${portrait(d)}</div><div class="panel-label"><h3>${escape(d.name)}</h3><button class="team-button ${state.team.includes(d.id)?'selected':''}" data-action="team" data-id="${d.id}">${state.team.includes(d.id)?'✓ Xuất chiến':'+ Đội hình'}</button></div><div class="subtitle">${d.element} linh căn · Cấp ${d.level} · ${G.ELEMENTS[d.element].bonus}</div><select class="job-select" data-job="${d.id}" aria-label="Giao việc cho ${escape(d.name)}">${jobOptions(d)}</select><div class="disciple-actions"><button class="btn secondary" data-action="disciple" data-id="${d.id}">Chi tiết</button><button class="btn" data-action="train" data-id="${d.id}">Tu luyện ↑</button></div><div class="small-note">Tu luyện: ${fmt(G.discipleCost(d).stone)} linh thạch · ${fmt(G.discipleCost(d).qi)} linh khí</div></article>`).join('')}</div>`;}
function chapterArt(index){return `<div class="chapter-illustration chapter-${index}" aria-hidden="true"><span class="chapter-glyph">${['竹','冰','炎','雲','雷'][index]}</span></div>`;}
function teamBar(){return `<div class="team-bar"><div class="portraits">${state.team.map(id=>state.disciples.find(d=>d.id===id)).filter(Boolean).map(d=>`<div class="portrait">${portrait(d)}</div>`).join('')}</div><div><strong>${fmt(G.power(state))} chiến lực</strong><p>${state.team.length}/5 đệ tử xuất chiến ${state.buff?'· Hộ Mạch Đan đang có hiệu lực':''}</p></div><button class="btn secondary" data-nav="disciples">Bày trận ${icon('arrow')}</button></div>`;}
function adventureMarkup(){return heading('Bí cảnh kỳ ngộ','Lập đội hình, dùng đan dược và chinh phục từng tầng thử thách.')+teamBar()+`${battle?.status==='fighting'?'<div class="guide-callout">Đội thám hiểm đang giao chiến.<button class="btn" data-action="battle">Xem trận đấu</button></div>':''}${state.scrolls?`<div class="guide-callout">${icon('scroll')}<span>Bạn còn ${state.scrolls} lần chiêu mộ miễn phí. Đủ 5 đệ tử sẽ dễ vượt bí cảnh hơn.</span><button class="btn secondary" data-action="recruit">Thu nhận đệ tử</button></div>`:''}<div class="chapter-grid">${G.CHAPTERS.map((c,i)=>`<article class="chapter-card ${i>state.chapter?'locked':''}"><div class="chapter-art">${chapterArt(i)}</div><div class="chapter-content"><div class="eyebrow">BÍ CẢNH 0${i+1}</div><h3>${c.name}</h3><p>${c.sub}</p><div class="chapter-meta"><span>${i>state.chapter?'Chưa mở khóa':state.stages[i]>=3?'Đã chinh phục · Có thể cày lại':'Tầng '+(state.stages[i]+1)+'/3'}</span><span>Khuyến nghị ${fmt(G.enemyPower(i,Math.min(state.stages[i],2)))}</span></div><button class="btn ${i>state.chapter?'secondary':''}" data-action="battle" data-id="${i}" ${i>state.chapter?'disabled':''}>${i>state.chapter?'Hoàn thành bí cảnh trước':'Xuất chiến'} ${icon('sword')}</button></div></article>`).join('')}</div><p class="version-note">Ba chiến thắng mở bí cảnh tiếp theo. Khi thất bại, đệ tử trở về an toàn và bạn có thể thử lại.</p>`;}
function alchemyMarkup(){return heading('Luyện Đan Các','Từ một nhành linh thảo, luyện thành cơ duyên trên đường phi thăng.')+`<div class="alchemy-notice">${icon('pill')}<span>Luyện Đan Các cấp ${state.buildings.alchemy} · Tụ Khí Đan nhận thêm ${10*(state.buildings.alchemy-1)} linh khí</span><button class="btn secondary" data-action="building" data-id="alchemy">Nâng cấp</button></div><div class="alchemy-grid">${G.RECIPES.map(r=>`<article class="recipe-card"><div class="recipe-art"><div class="pill-orb" style="--pill-color:${r.color}"></div></div><h3>${r.name}</h3><p>${r.desc}</p>${costMarkup(r.cost)}<button class="btn ${state.buildings.alchemy<r.level?'secondary':''}" data-action="craft" data-id="${r.id}">${state.buildings.alchemy<r.level?'Cần Luyện Đan Các cấp '+r.level:'Luyện đan'} ${icon('pill')}</button><div class="small-note">Trong túi: ${state.pills[r.id]} viên</div></article>`).join('')}</div>`;}
function inventoryMarkup(){const r=G.rates(state);return heading('Túi càn khôn','Tài nguyên và đan dược được lưu cùng tiến trình trên trình duyệt.')+`<div class="section-row"><h2>Tài nguyên tông môn</h2><small>Tăng trưởng tự động mỗi giây</small></div><div class="inventory-grid">${Object.entries(resourceNames).map(([k,n])=>`<div class="inventory-item">${icon(k)}<div><small>${n}</small><strong data-resource="${k}">${fmt(state[k])}</strong><small>+${fmt(r[k]*60)} / phút</small></div></div>`).join('')}<div class="inventory-item">${icon('scroll')}<div><small>Lệnh chiêu mộ</small><strong>${state.scrolls}</strong><small>Thu nhận đệ tử miễn phí</small></div><button class="btn secondary" data-action="recruit">Chiêu mộ</button></div></div><div class="section-row"><h2>Đan dược</h2><button class="btn ghost" data-nav="alchemy">Đến Luyện Đan Các ${icon('arrow')}</button></div><div class="inventory-grid">${G.RECIPES.map(r=>`<div class="inventory-item"><div class="pill-orb" style="--pill-color:${r.color};width:43px;height:43px;flex-shrink:0"></div><div><small>${r.name}</small><strong>${state.pills[r.id]}</strong><small>${r.id==='realm'?'Tự dùng khi đột phá':r.id==='qi'?'+120 linh khí':'Tăng sức mạnh một trận'}</small></div>${r.id==='realm'?'':`<button class="btn secondary" data-action="use" data-id="${r.id}" ${!state.pills[r.id]?'disabled':''}>Dùng</button>`}</div>`).join('')}</div>${state.buff?'<p class="good-label small-note">✓ Hộ Mạch Đan sẽ tăng 25% công và máu cho lần xuất chiến tiếp theo.</p>':''}`;}
function render(){document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===view));$('#view').innerHTML=({home:homeMarkup,disciples:disciplesMarkup,adventure:adventureMarkup,alchemy:alchemyMarkup,inventory:inventoryMarkup}[view]||homeMarkup)();renderHeader();}
function updateLive(){G.tick(state);document.querySelectorAll('[data-resource]').forEach(n=>n.textContent=view==='inventory'&&!n.closest('.topbar')?fmt(state[n.dataset.resource]):compact(state[n.dataset.resource]));const c=G.realmCost(state);if($('[data-qi-progress]'))$('[data-qi-progress]').textContent=fmt(state.qi)+' / '+fmt(c.qi);if($('[data-qi-bar]'))$('[data-qi-bar]').style.width=Math.min(100,state.qi/c.qi*100)+'%';if($('[data-power]'))$('[data-power]').textContent=fmt(G.power(state));document.querySelectorAll('[data-live-progress]').forEach(n=>n.style.width=(25+(Date.now()/150+markerPositions[n.dataset.liveProgress][0])%65)+'%');}
function openModal(title,content,kind='info'){currentModal=kind;modal.classList.toggle('battle-modal',kind==='battle');$('#modal-body').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close-button" data-action="close" aria-label="Đóng">×</button></div><div class="modal-content">${content}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();currentModal='';}
function buildingModal(id){const b=G.BUILDINGS.find(x=>x.id===id);if(!b)return;const assignments=state.disciples.filter(d=>d.job===id);openModal(b.name,`<div class="building-modal-icon">${icon(id==='hall'?'home':id==='alchemy'?'pill':id)}</div><p>${b.desc}</p><div class="detail-grid"><div class="detail-stat"><small>Cấp công trình</small><strong>${state.buildings[id]} / 10</strong></div><div class="detail-stat"><small>${b.resource?'Sản lượng / phút':'Công thức mở'}</small><strong>${b.resource?fmt(G.rates(state)[b.resource]*60):state.buildings.alchemy>=2?'3 / 3':'2 / 3'}</strong></div><div class="detail-stat"><small>${id==='hall'?'Đệ tử tối đa':'Đệ tử làm việc'}</small><strong>${id==='hall'?G.capacity(state):assignments.length}</strong></div></div>${state.buildings[id]>=10?'<p class="good-label">Công trình đã đạt cấp tối đa.</p>':`<p>Nâng cấp lên ${state.buildings[id]+1}:</p>${costMarkup(G.upgradeCost(state,id))}`}<div class="modal-actions"><button class="btn" data-action="upgrade" data-id="${id}" ${state.buildings[id]>=10?'disabled':''}>Nâng cấp công trình ${icon('arrow')}</button><button class="btn secondary" ${id==='alchemy'?'data-nav="alchemy"':'data-nav="disciples"'}>${id==='alchemy'?'Luyện đan':'Giao việc đệ tử'}</button></div>`,'building:'+id);}
function discipleModal(id){const d=state.disciples.find(x=>x.id===+id);if(!d)return;const f=G.fighter(d,state);openModal(escape(d.name),`<div class="modal-art">${portrait(d)}</div><p style="text-align:center">${d.rarity} · ${d.element} linh căn · ${G.ELEMENTS[d.element].bonus}</p><div class="detail-grid"><div class="detail-stat"><small>Công kích</small><strong>${f.atk}</strong></div><div class="detail-stat"><small>Sinh lực</small><strong>${f.maxHp}</strong></div><div class="detail-stat"><small>Phòng ngự</small><strong>${f.def}</strong></div></div><p><b>${G.ELEMENTS[d.element].skill}</b> · Tích lũy 3 lượt để thi triển kỹ năng${d.element==='Mộc'?', hồi máu cho đồng đội bị thương':', gây 190% sát thương'}.</p><select class="job-select" data-job="${d.id}" aria-label="Giao việc cho ${escape(d.name)}">${jobOptions(d)}</select>${costMarkup(G.discipleCost(d))}<div class="modal-actions"><button class="btn" data-action="train" data-id="${d.id}">Tu luyện · Cấp ${d.level} → ${Math.min(50,d.level+1)}</button><button class="btn secondary" data-action="team" data-id="${d.id}">${state.team.includes(d.id)?'Rút khỏi đội':'Thêm vào đội hình'}</button></div>`,'disciple:'+id);}
function realmModal(){const full=state.realm>=G.REALMS.length-1;openModal('Đột phá cảnh giới',`<div class="modal-art">${portrait({element:'Thủy',appearance:1},true)}</div><div class="realm-path">${G.REALMS.map((r,i)=>`<span class="${i===state.realm?'current':i<state.realm?'past':''}">${r}</span>`).join('')}</div><p>${full?'Bạn đã chạm tới đỉnh cao của tiên đạo.':`Từ ${G.REALMS[state.realm]} đến ${G.REALMS[state.realm+1]}. Mỗi cảnh giới tăng sức mạnh cơ bản của toàn đội thêm 25%.`}</p>${full?'':costMarkup(G.realmCost(state))}${state.realm>=1&&!full?`<p>${icon('pill')} Trúc Cơ Đan: ${state.pills.realm}/1 · Tự tiêu hao khi đột phá.</p>`:''}<div class="modal-actions">${full?'':`<button class="btn gold" data-action="breakthrough">Đột phá ${G.REALMS[state.realm+1]} ${icon('qi')}</button>`}<button class="btn secondary" data-nav="alchemy">Chuẩn bị đan dược</button></div>`,'realm');}
function recruitModal(){if(state.disciples.length>=G.capacity(state)){openModal('Tiên môn cần rộng hơn',`<p>Tông môn đang có ${state.disciples.length}/${G.capacity(state)} đệ tử. Nâng Tông Môn Điện để mở thêm chỗ.</p><button class="btn" data-action="building" data-id="hall">Nâng Tông Môn Điện</button>`);return;}openModal('Một cuộc gặp, một tiên duyên',`<div class="modal-art">${portrait({element:'Mộc',appearance:3})}</div><p style="text-align:center">Một vị khách đang chờ trước sơn môn. Mỗi 5 lần chiêu mộ chắc chắn gặp một đệ tử Thiên tài.<br>Lần chiêu mộ tiếp theo: ${state.stats.recruits+1} · Còn ${5-state.stats.recruits%5} lần tới bảo đảm Thiên tài.</p><div class="modal-actions" style="justify-content:center"><button class="btn gold" data-action="confirm-recruit">${state.scrolls?'Dùng lệnh chiêu mộ · Miễn phí ('+state.scrolls+')':'Thu nhận · '+fmt(G.recruitCost(state))+' linh thạch'} ${icon('users')}</button></div><p class="small-note" style="text-align:center;margin-top:15px">Thường 38% · Hiếm 50% · Thiên tài 12%</p>`,'recruit');}
function revealRecruit(d){openModal('Tiên duyên đã tới',`<div class="recruit-reveal"><div class="modal-art">${portrait(d)}</div><h3>${escape(d.name)}</h3><p class="subtitle">${d.rarity} · ${d.element} linh căn</p><p>${G.ELEMENTS[d.element].bonus}. Đệ tử đã bắt đầu tu luyện tại Tụ Linh Trận${state.team.includes(d.id)?' và gia nhập đội hình xuất chiến':''}.</p><div class="modal-actions" style="justify-content:center"><button class="btn" data-action="disciple" data-id="${d.id}">Giao việc & tu luyện</button><button class="btn secondary" data-action="recruit">Chiêu mộ tiếp</button></div></div>`,'reveal');sound('recruit');}
function helpModal(){openModal('Tiên đồ bắt đầu từ đây',`<div class="help-steps">${[['01','Thu nhận đệ tử','Bạn có sẵn 2 lệnh miễn phí. Vào Đệ tử, giao việc theo linh căn để tăng sản lượng.'],['02','Xây dựng tiên môn','Chạm tên công trình trên bản đồ để nâng cấp. Tông Môn Điện mở thêm chỗ cho đệ tử.'],['03','Tu luyện & luyện đan','Tĩnh tâm để lấy linh khí. Nâng cấp đệ tử, luyện đan và đột phá để mạnh hơn.'],['04','Khám phá bí cảnh','Lập đội tối đa 5 đệ tử. Chiến đấu tự động, dùng kỹ năng mỗi 3 lượt. Ba chiến thắng mở vùng kế tiếp.'],['05','An tâm nghỉ ngơi','Tiến trình tự lưu trên trình duyệt. Khi quay lại, nhận tài nguyên nghỉ tối đa 8 giờ. Cài đặt cho phép xuất/nhập tiến trình.']].map(([n,t,p])=>`<div class="help-step"><b>${n}</b><div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}</div><div class="modal-actions"><button class="btn" data-action="close">Bắt đầu tiên đồ ${icon('arrow')}</button></div>`,'help');}
function settingsModal(){openModal('Một khoảng an nhiên',`<div class="settings-stack"><p>Tiến trình lưu trên trình duyệt này. Xuất tệp để sao lưu hoặc chuyển thiết bị. Bản chơi thử dành cho một người chơi.</p><button class="btn secondary" data-action="sound">${icon('sound')} ${state.sound?'Tắt':'Bật'} âm thanh</button><button class="btn secondary" data-action="export">${icon('scroll')} Xuất tiến trình (.json)</button><button class="btn secondary" data-action="import">${icon('bag')} Nhập tiến trình</button><button class="btn secondary" data-action="help">Hướng dẫn chơi</button><button class="btn danger" data-action="reset">Bắt đầu lại tiên đồ</button><p class="small-note">Thanh Vân Tông v1.1 · Game nguyên bản lấy cảm hứng từ thể loại tu tiên và quản lý tông môn. Hình ảnh, nhân vật và cân bằng được thiết kế riêng.</p></div>`,'settings');}
function fighterMarkup(f){return `<div class="fighter ${f.side} ${f.hp<=0?'dead':''}" id="fighter-${f.side}-${f.id}"><div class="portrait">${f.side==='ally'?portrait(f):beast(f)}</div><div class="progress"><span style="width:${f.hp/f.maxHp*100}%"></span></div><div class="energy">${[1,2,3].map(n=>`<i class="${f.energy>=n?'lit':''}"></i>`).join('')}</div><span class="name">${escape(f.name)}</span></div>`;}
function renderBattle(event){if(currentModal!=='battle'||!battle)return;const b=battle;const body=$('#modal-body .modal-content');const result=b.status!=='fighting';body.innerHTML=`<div class="battle-scene"><img class="battle-bg" src="assets/battle-courtyard.webp?v=2.2.0" alt=""><div class="battle-top">${G.CHAPTERS[b.chapter].name} · Tầng ${b.stage+1} · Hiệp ${Math.max(1,b.round)}</div><div class="battle-formation"><div class="battle-side">${b.allies.map(fighterMarkup).join('')}</div><div class="versus">VS</div><div class="battle-side enemy">${b.enemies.map(fighterMarkup).join('')}</div></div></div><div class="battle-log">${b.events.slice(0,3).map(e=>`<p>${escape(e.text)}</p>`).join('')||'<p>Các đệ tử vào trận. Linh khí đang hội tụ…</p>'}</div>${result?`<div class="battle-result"><h3>${b.status==='won'?'Bí cảnh đã bình yên':'Tạm lui, dưỡng sức'}</h3><p>${b.status==='won'?'Tiên duyên đã thu nhận. Phần thưởng được đưa vào túi đồ.':'Đệ tử đã trở về an toàn. Tu luyện và bổ sung đội hình để thử lại.'}</p>${b.result?.reward?costMarkup(b.result.reward):''}<div class="modal-actions" style="justify-content:center"><button class="btn" data-action="battle" data-id="${b.chapter}">${b.status==='won'?'Tiếp tục thám hiểm':'Tái chiến'}</button><button class="btn secondary" data-nav="disciples">Bồi dưỡng đệ tử</button></div></div>`:`<div class="battle-controls"><small>${b.usedBuff?'Hộ Mạch Đan: +25% sức mạnh':'Đệ tử tự thi triển kỹ năng sau 3 lượt'}</small><button class="btn secondary" data-action="speed">Tốc độ ×${battleSpeed}</button></div>`}`;
 if(event){const actor=$(`#fighter-${event.side}-${event.actor}`),target=$(`#fighter-${event.targetSide}-${event.target}`);actor?.classList.add('attacking');target?.classList.add(event.heal?'healed':'hurt');if(target){const n=document.createElement('span');n.className='damage '+(event.heal?'heal':'');n.textContent=(event.heal?'+':'−')+event.amount;target.append(n);}if(event.skill)sound('skill');}}
function startBattle(ch){if(battle?.status==='fighting'){openModal('Bí cảnh · Đội thám hiểm', '', 'battle');renderBattle();return;}const start=G.beginBattle(state,Number.isInteger(ch)?ch:state.chapter);if(start.error){toast(start.error,'error');return;}battle=start.battle;openModal('Bí cảnh · Đội thám hiểm','','battle');renderBattle();save();render();runBattle();}
function runBattle(){clearInterval(battleTimer);battleTimer=setInterval(()=>{if(!battle||battle.status!=='fighting'){clearInterval(battleTimer);return;}const e=G.battleStep(battle);if(battle.status!=='fighting'){battle.result=G.settleBattle(state,battle);save();render();sound(battle.status==='won'?'recruit':'tap');if(currentModal!=='battle')toast(battle.status==='won'?'Đội thám hiểm chiến thắng! Đã nhận tài nguyên.':'Đội thám hiểm đã trở về. Hãy tu luyện thêm.');clearInterval(battleTimer);}renderBattle(e);},battleSpeed===1?420:160);}
let audioContext=null;function sound(kind='tap'){if(!state.sound)return;try{audioContext ||=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const t=audioContext.currentTime;const tones=kind==='recruit'?[523,659,784,1047]:kind==='skill'?[440,880]:[440];tones.forEach((hz,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=hz;g.gain.setValueAtTime(0,t+i*.09);g.gain.linearRampToValueAtTime(.035,t+i*.09+.02);g.gain.exponentialRampToValueAtTime(.001,t+i*.09+.28);o.connect(g);g.connect(audioContext.destination);o.start(t+i*.09);o.stop(t+i*.09+.3);});}catch{}}
function actionDone(error,message){if(error){toast(error,'error');return false;}if(message)toast(message);sound();save();render();return true;}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){view=nav.dataset.nav;closeModal();render();window.scrollTo({top:0,behavior:'smooth'});return;}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;G.tick(state);const a=el.dataset.action,id=el.dataset.id;
switch(a){case 'close':closeModal();break;case 'help':helpModal();break;case 'settings':settingsModal();break;
case 'building':buildingModal(id);break;case 'upgrade':if(actionDone(G.upgrade(state,id),'Công trình đã được nâng cấp.'))buildingModal(id);break;
case 'disciple':discipleModal(+id);break;case 'train':if(actionDone(G.train(state,+id),'Đệ tử đã tiến thêm một bậc.')){if(currentModal.startsWith('disciple:'))discipleModal(+id);}break;
case 'team':if(actionDone(G.toggleTeam(state,+id),'Đã cập nhật đội hình.')){if(currentModal.startsWith('disciple:'))discipleModal(+id);}break;
case 'meditate':if(G.meditate(state)){sound();updateLive();toast('Tĩnh tâm · +'+(12+state.buildings.qi*3+state.realm*5)+' linh khí');save();}break;
case 'realm':realmModal();break;case 'breakthrough':if(actionDone(G.breakthrough(state),'Đột phá thành công!'))realmModal();break;
case 'recruit':recruitModal();break;case 'confirm-recruit':{const r=G.recruit(state);if(r.error){toast(r.error,'error');return;}save();render();revealRecruit(r.disciple);break;}
case 'craft':actionDone(G.craft(state,id),'Luyện thành công '+G.RECIPES.find(r=>r.id===id).name+'.');break;
case 'use':actionDone(G.usePill(state,id),id==='power'?'Đội hình đã được tăng sức mạnh cho trận tiếp theo.':'Linh khí đã được bổ sung.');break;
case 'claim':actionDone(G.claim(state,id),'Đã nhận thưởng tiên môn ký sự.');break;
case 'battle':startBattle(id===undefined?undefined:+id);break;case 'speed':battleSpeed=battleSpeed===1?3:1;runBattle();renderBattle();break;
case 'sound':state.sound=!state.sound;if(state.sound)sound('recruit');save();renderHeader();if(currentModal==='settings')settingsModal();toast(state.sound?'Đã bật âm thanh thao tác.':'Đã tắt âm thanh.');break;
case 'export':{G.tick(state);save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Thanh-Van-Tong-tien-trinh.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất tiến trình.');break;}
case 'import':if(battle?.status==='fighting'){toast('Chờ trận đấu kết thúc trước khi nhập tiến trình.','error');return;}$('#import-save').click();break;
case 'confirm-import':if(importCandidate){state=importCandidate;importCandidate=null;battle=null;save();closeModal();render();toast('Đã khôi phục tiến trình.');}break;
case 'reset':if(battle?.status==='fighting'){toast('Chờ trận đấu kết thúc trước khi bắt đầu lại.','error');return;}openModal('Bắt đầu một tiên đồ mới?',`<p>Toàn bộ tài nguyên, đệ tử và tiến trình hiện tại sẽ bị xóa trên thiết bị này. Bạn có thể xuất tiến trình trong Cài đặt trước khi bắt đầu lại.</p><div class="modal-actions"><button class="btn danger" data-action="confirm-reset">Xóa tiến trình và bắt đầu lại</button><button class="btn secondary" data-action="settings">Giữ tiên đồ hiện tại</button></div>`,'reset');break;
case 'confirm-reset':state=G.newGame();battle=null;view='home';save();closeModal();render();toast('Thanh Vân Tông khai sơn lần nữa.');break;
}});
document.addEventListener('change',e=>{if(e.target.matches('[data-job]')){G.assign(state,+e.target.dataset.job,e.target.value);save();render();toast('Đã giao việc cho đệ tử.');}});
$('#import-save').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>200000){toast('Tệp tiến trình quá lớn.','error');return;}try{const text=await file.text(),data=JSON.parse(text);if(!G.validSave(data))throw Error();importCandidate=G.restore(text).state;openModal('Khôi phục tiên đồ?',`<p>Tiến trình trong tệp: ${importCandidate.disciples.length} đệ tử · ${G.REALMS[importCandidate.realm]} · ${fmt(importCandidate.stone)} linh thạch.<br>Nhập tệp sẽ thay thế tiến trình hiện tại trên thiết bị.</p><div class="modal-actions"><button class="btn" data-action="confirm-import">Khôi phục tiến trình này</button><button class="btn secondary" data-action="close">Giữ tiến trình hiện tại</button></div>`,'import');}catch{toast('Tệp không phải tiến trình Thanh Vân Tông hợp lệ.','error');}});
modal.addEventListener('click',e=>{if(e.target===modal)closeModal();});modal.addEventListener('close',()=>{currentModal='';});
window.addEventListener('pagehide',()=>{G.tick(state);save();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateLive();save();}});
render();save();setInterval(updateLive,1000);setInterval(save,5000);
if(restored.offline){const o=restored.offline;openModal('Tông sư đã trở về',`<div class="modal-art">${portrait({element:'Thủy',appearance:1},true)}</div><p style="text-align:center">Khi người nghỉ, tiên môn vẫn sinh sôi.<br>Đã nhận tài nguyên của ${o.secs>=3600?(o.secs/3600).toFixed(1)+' giờ':Math.floor(o.secs/60)+' phút'} nghỉ ngơi (tối đa 8 giờ).</p><div class="offline-grid">${Object.entries(o.gains).map(([k,v])=>`<div class="detail-stat">${icon(k)}<small>${resourceNames[k]}</small><strong>+${fmt(v)}</strong></div>`).join('')}</div><div class="modal-actions"><button class="btn block" data-action="close">Tiếp tục tiên đồ ${icon('arrow')}</button></div>`,'offline');}
if(restored.recovered)toast('Tiến trình cũ không hợp lệ. Đã tạo tiên đồ mới.','error');
